"""
    _ann_forward_deep(x1, x2)

Forward pass of the deep trained multilayer perceptron: a dual-input first layer (`x1` 15-dim,
`x2` 4-dim), tanh hidden layers 2-10, and a linear output layer 11 (95-dim) — 11 layers in total,
with min-max scaling on the inputs and inverse scaling on the output. Ported from the MATLAB
Neural Network Toolbox `genFunction` output (`TRCM_Z_Deep_NeuralNetworkFunction` in
`SULoop_TRCMz_ANN.m`).
"""
function _ann_forward_deep(x1, x2)
    xp1 = _mapminmax_apply(x1, _input_scaler1_deep)
    xp2 = _mapminmax_apply(x2, _input_scaler2_deep)

    # Layer 1: combines both inputs.
    a = tanh.(_b_deep[1] .+ _IW1_1_deep * xp1 .+ _IW1_2_deep * xp2)
    # Layers 2-10: standard tanh hidden layers.
    for l in 2:10
        a = tanh.(_b_deep[l] .+ _LW_deep[l-1] * a)
    end
    # Layer 11: linear output (no tanh).
    y11 = _b_deep[11] .+ _LW_deep[10] * a

    return _mapminmax_reverse(y11, _output_scaler_deep)
end

"""
    _feature_vectors_deep(ks, Cs, kg, Cg, kp, Cp, Cf, rb, ri, e, H, V̇, D, L)

Assemble the two feature vectors consumed by the deep ANN from the (already validated) physical
parameters, mirroring `SULoop_TRCMz_ANN.m`'s construction of `P{1}` (15-dim) and `P{2}` (4-dim):
```
P{1} = [ks, Cs, kg, Cg, kp, Cf, rb, ri, e, H, V̇, D, log(ks/Cs), log(kg/Cg), log(kp/Cp)]
P{2} = [L, L/(2H), 2H/u, L·2H/u]   with u = V̇ / (π·ri²)
```
`e = ro - ri` is the pipe wall thickness and `L` is the flow-path distance from the inlet (see
`short_term_nodes(::DeepANN, ...)`; the outlet corresponds to `L = 2H`). `Cp` only enters through
the `log(kp/Cp)` term — it does not otherwise appear in `P{1}` (it is skipped when the other 12
raw parameters are selected, exactly as in the MATLAB source).
"""
function _feature_vectors_deep(ks, Cs, kg, Cg, kp, Cp, Cf, rb, ri, e, H, V̇, D, L)
    P1 = [ks, Cs, kg, Cg, kp, Cf, rb, ri, e, H, V̇, D,
        log(ks / Cs), log(kg / Cg), log(kp / Cp)]
    u = V̇ / (π * ri^2)
    P2 = [L, L / (2H), 2H / u, L * 2H / u]
    return P1, P2
end

"""
    _input_validation_deep(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s; clamp=true)

Check the 13 physical inputs against the deep ANN's (wider) training ranges. Same `clamp` policy
as `_input_validation` (the published net's). Returns the validated
`(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, D)`, where the half-shank spacing `D = s / 2` is
derived from the shank spacing `s`.
"""
function _input_validation_deep(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s;
    clamp::Bool = true)

    # Lower/upper bound of every physical parameter (see the validity ranges in the docstring of
    # `short_term_nodes(::DeepANN, ...)`).
    p_limit = [
        0.25                             8;                # ks
        1.4e6                            3e6;              # Cs
        0.25                             5;                # kg
        1.4e6                            3e6;              # Cg
        0.3                              1.0;              # kp
        1.9e6                            1.9e6;             # Cp
        3.8e6                            4.3e6;             # Cf
        0.012                            0.027;             # ri
        0.015                            0.036;             # ro
        2 * ro + 2e-3                    0.1;               # rb
        50                               250;               # H
        15 / 1000 / 60                   35 / 1000 / 60;    # V̇ (15-35 L/min)
        2 * (0.01 * (rb - 2 * ro) + ro)   2 * (0.99 * (rb - 2 * ro) + ro)  # s (= 2·half-shank D)
    ]

    params = [ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s]
    p_names = ["ks", "Cs", "kg", "Cg", "kp", "Cp", "Cf", "ri", "ro", "rb", "H", "V̇", "s"]
    p_units = ["W/mK", "J/Km³", "W/mK", "J/Km³", "W/mK", "J/Km³", "J/Km³", "m", "m", "m", "m",
        "m³/s", "m"]

    for i in eachindex(params)
        lo, hi = p_limit[i, 1], p_limit[i, 2]
        if params[i] < lo || params[i] > hi
            bound = params[i] < lo ? lo : hi
            msg = "Parameter $(p_names[i]) = $(params[i]) $(p_units[i]) is outside the DeepANN " *
                  "training range [$lo, $hi] $(p_units[i])"
            if clamp
                @warn "$msg — clamped to $bound $(p_units[i])"
                params[i] = bound
            else
                @error msg
                throw(ArgumentError(msg))
            end
        end
    end

    ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s = params
    return ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s / 2
end

"""
    _validate_time_deep(t; clamp=true)

Check the requested evaluation time(s) `t` against the deep ANN's short-term horizon (15 s –
21 days), applying the same `clamp` policy as `_input_validation_deep`. Mirrors `_validate_time`
(the published net's), with the wider horizon.
"""
function _validate_time_deep(t; clamp::Bool = true)
    lo, hi = 15, 21 * 24 * 3600
    tlast = last(t)
    (lo <= tlast <= hi) && return t

    bound = tlast < lo ? lo : hi
    msg = "Final evaluation time t = $tlast s is outside the DeepANN short-term range [$lo, $hi] s"
    if !clamp
        @error msg
        throw(ArgumentError(msg))
    end
    @warn "$msg — clamped to $bound s"
    if t isa AbstractVector
        t = float.(t)
        t[end] = bound
        return t
    else
        return bound
    end
end

"""
    short_term_nodes(::DeepANN, ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s; clamp=true)

Evaluate the deep ANN (Pasquier & Marcotte, 2020 / `SULoop_TRCMz_ANN.m`) on its 95 fixed native
time nodes, returning `(ts, g)` — see `short_term_nodes(::PublishedANN, ...)` for the general
contract (no interpolation, no time validation). Unlike the published net, this network can in
principle report the temperature at an arbitrary probe location along the U-tube (parametrised by
a flow-path distance `L` from the inlet, `0 ≤ L ≤ 2H`); **only the borehole outlet is exposed
here** (`L = 2H`, i.e. `Data.T_Probe_Location = [0; 5]` in the MATLAB source — depth `z = 0` on the
ascending/return leg, id `5`, so `L = 2H - z = 2H`), matching the published net's outlet-only
signature. Inverts the training transformation
`g = ts / exp((exp(y) - 4.5) + ym) - 1` (`y` the raw 95-dim linear output of the network, `ym` a
per-node constant fit during training — not the same formula as the published net's
`y = ln(ts / (g + 1))`).
# Validity ranges (ANN training bounds)
    - t: 15 s – 21 days (horizon applied to the last value)
    - ks: 0.25–8 W/mK
    - Cs: 1.4–3 MJ/m³K
    - kg: 0.25–5 W/mK
    - Cg: 1.4–3 MJ/m³K
    - kp: 0.3–1.0 W/mK
    - Cp: 1.9 MJ/m³K (fixed)
    - Cf: 3.8–4.3 MJ/m³K
    - ri: 0.012–0.027 m
    - ro: 0.015–0.036 m
    - rb: (2ro+2mm)–0.1 m
    - H: 50–250 m
    - V̇: 15–35 L/min
    - s: 2(0.01(rb-2ro)+ro) – 2(0.99(rb-2ro)+ro) m (twice the half-shank spacing)
# Reference
    - Pasquier, P., & Marcotte, D. (2020). Robust identification of volumetric heat capacity and
        analysis of thermal response tests by Bayesian inference with correlated residuals.
        Applied Energy, 261, 114394. https://doi.org/10.1016/j.apenergy.2019.114394
"""
function short_term_nodes(::DeepANN, ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s;
    clamp::Bool = true)
    ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, D =
        _input_validation_deep(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s; clamp = clamp)

    e = ro - ri
    L = 2H  # Outlet special case: Data.T_Probe_Location = [0; 5] (ascending leg, z = 0) ⇒ L = 2H.
    P1, P2 = _feature_vectors_deep(ks, Cs, kg, Cg, kp, Cp, Cf, rb, ri, e, H, V̇, D, L)

    y = _ann_forward_deep(P1, P2)
    g = _ST_NODES_DEEP ./ exp.((exp.(y) .- 4.5) .+ _ym_deep) .- 1
    g[g.<0] .= 0

    return _ST_NODES_DEEP, g
end

"""
    short_term_response(::DeepANN, t, rb, ri, ro, H, s, V̇, ks, Cs, kg, Cg, kp, Cp, Cf; clamp=true)

Short-term transfer function of the borehole-**outlet** fluid temperature from the deep ANN
(Pasquier & Marcotte, 2020), PCHIP-interpolated onto arbitrary `t` from the 95 native nodes of
[`short_term_nodes`](@ref). Same argument order and meaning as
`short_term_response(::PublishedANN, ...)`; see `short_term_nodes(::DeepANN, ...)` for the
validity ranges and the outlet-only caveat.
"""
function short_term_response(::DeepANN, t, rb, ri, ro, H, s, V̇, ks, Cs, kg, Cg, kp, Cp, Cf;
    clamp::Bool = true)
    _, g_nodes = short_term_nodes(DeepANN(), ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s;
        clamp = clamp)

    t = _validate_time_deep(t; clamp = clamp)

    g = pchip_interpolation(_ST_NODES_DEEP, g_nodes, t)

    return t, g
end
